text:
Go で関数を定義するには `func` を使います。Python の `def` との一番の差は、**引数に型を書く**ことです。引数名の後ろに型を置き、同じ型が続くときは `a, b int` とまとめて書けます。型の合わない値を渡す呼び出しはコンパイルエラーになるので、実行する前に間違いに気づけます。🔴 関数定義はこの先すべての土台になるので、手が覚えるまで書きましょう。

Python ではこう書いた:

```python
def greet(name, times):
    for i in range(times):
        print("Hello,", name)
```

Go ではこう書く:

```go
func greet(name string, times int) {
	for range times {
		fmt.Println("Hello,", name)
	}
}
```

sample:
// lesson18 ch01: func と引数の型
package main

import "fmt"

// greet は名前と回数を受け取ってあいさつを出力します。
// 引数には名前のあとに必ず型を書きます（name string, times int）
func greet(name string, times int) {
	for range times {
		fmt.Println("Hello,", name)
	}
}

// 同じ型が続くときは a, b int とまとめて書けます
func printSum(a, b int) {
	fmt.Println(a + b)
}

func main() {
	greet("Gopher", 2)
	printSum(3, 5)
}

exercise.starter:
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// ここに printSum(a, b int) を定義する

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	fields := strings.Fields(sc.Text())
	a, _ := strconv.Atoi(fields[0])
	b, _ := strconv.Atoi(fields[1])
	// ここから下を書く（printSum を呼び出す）
	_, _ = a, b
	_ = fmt.Println
}

exercise.answer:
// lesson18 ch01 解答
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// 引数には名前のあとに型を書きます。同じ int が続くので a, b int とまとめました。
// 型を書いておくと printSum("x", 1) のような誤った呼び出しが
// コンパイル時に弾かれるのが Python の def との大きな差です。
func printSum(a, b int) {
	fmt.Println(a + b)
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	fields := strings.Fields(sc.Text())
	a, _ := strconv.Atoi(fields[0])
	b, _ := strconv.Atoi(fields[1])
	printSum(a, b)
}
